    assert r1['verification']['execution_gate_pass']
    p = {'round': 'R2', 'frozen_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'claim_type': 'capability', 'parent_results_sha256': sha(ROOT / 'raw/RESULTS_R1.json'), 'parent_PREREG_sha256': sha(ROOT / 'PREREG_R1.json'), 'capability': 'Return finite-box model enclosures and inverse matched measurement requirements for two manufacturing routes on D1', 'obstacle': 'R1 mean/histogram is insufficient and most optical rays are outside source support; no coupon-to-crown validation', 'changed_operation': 'Replace bulk-property acceptance by location-preserving intervals and the preimage of the fixed decision threshold; freeze actual matched lab targets', 'consumer': 'Laboratory deciding which D1 sintering/cure prototypes to make and measure', 'metrics': {'all_model_box_samples_enclosed': True, 'injected_bad_enclosure_rejected': True, 'unchanged_R1_PREREG_and_results': True, 'physical_release_without_matched_assay': 'UNKNOWN'}, 'TM02': {'TP_floor': 12.0, 'geometry_scenario_halfwidth_mm': 0.12, 'geometry_scenario_is_rigorous_physical_bound': False, 'knot0_mm_box': [0.49, 0.51], 'knot1_mm_box': [0.99, 1.01], 'TP_boxes': 'Published observed min/max at each thickness, no future coverage probability', 'model': 'Two-knot log-affine TP law only if entire query length box lies between all possible source knots', 'arithmetic': 'Monotonicity proof makes extrema occur at corners; each corner evaluated with outward interval arithmetic at 30 decimal digits', 'inverse_query': 'Required additive TP transfer offset beta >=12-model_lower, only on supported rays; outside support request direct surface TP instead', 'minimum_measurement': 'Without a spatial/monotone law every exposed sample needs a TP assay. One worst-length point per route suffices only under a homogeneous monotone TP law, which is an explicit unvalidated closure', 'resolution_level': 'PER_POINT target; PHENOMENOLOGICAL closure; POPULATION source', 'time_scale': 'HANDOVER'}, 'TM05': {'force_N': 150.0, 'strength_box': 'mean +/-2 reported SD, clipped at0; finite source-data scenario, not a statistical tolerance interval', 'stress_box': 'Frozen facet stress field exactly as computed; FE discretization, load-dependent contact and physical modulus uncertainty remain unbounded', 'inverse_query': 'Under uniform strength scale alpha, alpha_required=peak_demand/mean_strength; actual uniform alpha is UNKNOWN', 'matched_assay': 'Measured D1 fracture load F_test tests this particular loadcase directly; same batch/contact/die and fracture origin needed to interpret alpha', 'resolution_level': 'PER_SURFACE_REGION demand/assay query; POPULATION source', 'time_scale': 'HANDOVER'}, 'strongest_equally_informed_control': 'Direct all-facet inequalities plus independent dense corner enumeration and interval containment. Same sources and scope. No algorithm claim', 'falsifiers': ['Any sampled finite-box model escapes its computed enclosure', 'Narrowed injected interval accepted', 'Unsupported optical ray accepted', 'Predicted crown result labeled measured', 'Source-box agreement used as future population coverage'], 'full_cost': {'prepare': 'Reuse R1 field results and hashes; charge inherited geometry and FE', 'fit': 0, 'discovery': 'Two bounded interval/inverse consumers, no new FE', 'validation': 'Published quantities, adverse input, high-precision corners and fixed-seed box samples', 'questions': 0, 'fallback': 'Matched optical/crown assay request; no invented calibration', 'physical': 'Not performed; timing and lab costs UNMEASURED'}, 'external_referent': r1['external_referent'], 'numerical_limit': 'Rigorous arithmetic enclosure of the declared surrogate/source boxes only. No rigorous continuum geometry/FE enclosure and no patient-specific prediction validation.'}
    dump(ROOT / 'PREREG_R2.json', p)
    (ROOT / 'PREREG_R2.sha256').write_text(sha(ROOT / 'PREREG_R2.json') + '\n')
    dump(ROOT / 'DECOMPOSITION_R2.json', {'leaves': [{'status': 'DERIVED_UNDER_ASSUMPTIONS', 'equation': 'y=exp((1-w)log y0+w log y1); w=(h-a)/(b-a); y0>y1>0 and a<=h<=b. Positive derivatives in y0,y1,a,b and negative derivative in h put extrema at corners.', 'operation': 'Interval-evaluated finite-box corner extrema', 'representation': 'joint process/two-knot/geometry box', 'stop_argument': 'This law has only two published thickness points and no held-out optical validation.'}, {'status': 'DERIVED_UNDER_ASSUMPTIONS', 'equation': 'r_min=min_i S_i/d_i; uniform-scale alpha_required=max_i d_i/mu', 'operation': 'Exact local demand query then invert fixed threshold', 'representation': 'location preserving demand field and process-specific source rows', 'stop_argument': 'Alpha does not identify modulus, defects or contact; one fracture load cannot estimate a reliability distribution.'}, {'status': 'CONSTITUTIVE_CLOSURE', 'equation': 'source strength mean +/-2SD and optical observed ranges define scenarios, not population confidence', 'operation': 'Screen only within declared boxes', 'representation': 'dimensioned source bounds', 'stop_argument': 'Individual raw source data and matched D1 assay absent.'}, {'status': 'UNKNOWN', 'equation': 'physical TP(surface) and D1 fracture response vs predictions', 'operation': 'matched spectroscopy and force-displacement assay', 'representation': 'batch/region/loadcase tagged measurements', 'stop_argument': 'Cannot identify these from unrelated source coupons or ray geometry.'}]})
